mapper.insert:

	SELECT SEQ_MOCK_ANALYSIS_GROUP.nextval FROM DUAL

insert into MOCK_GROUP(
	GROUP_NO, STUDENT_NO, YEAR_MONTH, STATUS
) VALUES(
	#{groupNo}
	,#{studentNo}
	,#{yearMonth}
	,#{status}
)

mapper.update:
update MOCK_GROUP
set
  COMPLETED_AT = SYSDATE
  ,status = #{status}
where GROUP_NO = #{groupNo}

mapper.select:
select STATUS
from MOCK_GROUP
where GROUP_NO = #{groupNo}
